interface.definition:
#"SYSTEM_SYSRULES_formLayout_v1"(
  label: "",
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_cardLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                marginBelow: "NONE",
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      align: "CENTER",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(icon: "info-circle", size: "MEDIUM_PLUS",color: "NEGATIVE"),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          style: "STRONG",
                          size: "MEDIUM_PLUS",
                          text: {
                            " Task locked "
                          },
                          color: "NEGATIVE"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          size: "MEDIUM",
                          text: property(ri!task,"taskName",tostring(null)),
                          style: "STRONG"
                        ),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          size: "MEDIUM",
                          text: "is currently locked by "
                        ),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          size: "MEDIUM",
                          text: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(property(ri!task,"lockedBy",tostring(null))),
                          style: "STRONG"
                        )
                      }
                    )
                  )
                }
              )
            },
            style:"ERROR",
            marginBelow: "STANDARD",
            showShadow: true
          ),
          width: "WIDE"
        ),
        #"SYSTEM_SYSRULES_columnLayout"()
      }
    )
  },
  buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
    primaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
      label: "Close",
      submit: true,
      value: "Close",
      saveInto: {ri!action}
    )
  )
)
